/**
 * Choices drawn by code (topic merge plan G3, §5.4): every `[!choice]` callout in a source's text (`choices.ts`)
 * becomes plan nodes in its section, deterministically — never generated by a model, so it looks and reads the same
 * on every run and its objects are matched by key like any other.
 *
 * - **Open**: a "Needs your call" box (`<section> § choice:<id>`) and one card per option
 *   (`… § choice:<id>:option<i>`), each linked from the box by a dotted `option_of` link.
 * - **Chosen**: the box's own key now holds the chosen option (so the box object turns into it in place), the
 *   option cards are gone, and the section's "Changed over time" page (`<section> § trail`) lists what was chosen
 *   over what.
 * - **Revised** (G3.3, `revisions.ts`): where the text changed its mind, the same page lists what the earlier statement said.
 *
 * `withChoiceNodes` first removes any choice nodes the plan already has (a reused section brings its earlier ones),
 * then adds the current ones.
 */
import { UNIT_SEPARATOR } from "@/ai/reconcile/keys";
import { rekey, type PathIds } from "@/ai/reconcile/topicIds";
import { UNIT_SECTION_SUFFIX } from "@/ai/visual-plan/groups";
import type { VisualNode, VisualPlan } from "@/ai/visual-plan/types";
import { unitsOfSectionKey } from "@/ai/visualize/outline";
import { findChoices, type Choice } from "./choices";

const CHOICE = `${UNIT_SEPARATOR}choice:`;
const TRAIL = `${UNIT_SEPARATOR}trail`;
const LEAD_UNIT = "(lead)";

/** The key parts of a choice object (a box, a chosen card or an option card), from its stable key; null for any other. */
export function choiceOfKey(stableKey: string): { section: string; id: string; option: number | null } | null {
  const at = stableKey.indexOf(CHOICE);
  if (at < 0) return null;
  const [id, option] = stableKey.slice(at + CHOICE.length).split(":option");
  return { section: stableKey.slice(0, at), id: id!, option: option === undefined ? null : Number(option) };
}

const isChoiceNode = (n: VisualNode) => !!n.stableKey && (n.stableKey.includes(CHOICE) || n.stableKey.endsWith(TRAIL));

/** Each callout of `text` with the analysis unit it sits in (its heading path, rekeyed to topic ids). */
export function choicesInText(text: string, pathIds?: PathIds): { unit: string; choice: Choice }[] {
  return findChoices(text).map((choice) => ({ unit: rekey(unitAt(text, choice.span.start), pathIds), choice }));
}

/** The plan with its choice nodes redrawn from `choices` (any earlier ones removed first). */
export function withChoiceNodes(plan: VisualPlan, choices: readonly { unit: string; choice: Choice }[], revisions: readonly { unit: string; earlier: string; later: string }[] = []): VisualPlan {
  const dropped = new Set(plan.nodes.filter(isChoiceNode).map((n) => n.id));
  const nodes = plan.nodes.filter((n) => !dropped.has(n.id));
  const relationships = plan.relationships.filter((r) => !dropped.has(r.from) && !dropped.has(r.to));
  const trails = new Map<string, { section: string; lines: string[] }>();

  for (const { unit, choice } of choices) {
    const section = sectionOf(plan, unit);
    const parent = plan.nodes.find((n) => n.type === "group" && n.stableKey === `${section}${UNIT_SECTION_SUFFIX}`)?.id;
    const member = <T extends VisualNode>(n: T): T => (parent ? { ...n, parent } : n);
    const base = `${section}${CHOICE}${choice.id}`;
    const id = (suffix: string) => `choice_${hash(base)}${suffix}`;
    if (!choice.resolved) {
      nodes.push(
        member({
          id: id(""),
          type: "text",
          stableKey: base,
          title: "Needs your call",
          importance: "high",
          content: { markdown: `**${choice.title}**\n\nThese sources disagree, and nothing says which one is current. Select an option and choose “Use this option”.` },
        } as VisualNode),
      );
      choice.options.forEach((o, i) => {
        nodes.push(member({ id: id(`_o${i}`), type: "text", stableKey: `${base}:option${i}`, title: `Option ${i + 1}`, content: { markdown: `${o.statement}\n\n_${capital(o.from)}_` } } as VisualNode));
        relationships.push({ from: id(""), to: id(`_o${i}`), type: "option_of" });
      });
      continue;
    }
    const chosen = choice.options.find((o) => o.state === "chosen");
    if (!chosen) continue;
    nodes.push(member({ id: id(""), type: "text", stableKey: base, title: choice.title, content: { markdown: `${chosen.statement}\n\n_Chosen · ${chosen.from}_` } } as VisualNode));
    const others = choice.options.filter((o) => o.state === "not_chosen").map((o) => `“${o.statement}” (${o.from})`);
    const trail = trails.get(section) ?? { section, lines: [] };
    trail.lines.push(`- **${choice.title}**: chose “${chosen.statement}” (${chosen.from})${others.length ? ` over ${others.join(", ")}` : ""}.`);
    trails.set(section, trail);
  }
  // Where the text changed its mind (G3.3): the later statement won; the earlier one is kept here.
  for (const r of revisions) {
    const section = sectionOf(plan, r.unit);
    const trail = trails.get(section) ?? { section, lines: [] };
    trail.lines.push(`- Was “${r.earlier}” — now “${r.later}”`);
    trails.set(section, trail);
  }
  for (const { section, lines } of trails.values()) {
    const parent = plan.nodes.find((n) => n.type === "group" && n.stableKey === `${section}${UNIT_SECTION_SUFFIX}`)?.id;
    nodes.push({
      id: `trail_${hash(section)}`,
      type: "page",
      stableKey: `${section}${TRAIL}`,
      ...(parent ? { parent } : {}),
      content: { title: "Changed over time", markdown: lines.join("\n") },
    } as VisualNode);
  }
  return { ...plan, nodes, relationships };
}

/** The section of the plan holding `unit`: a section heading or group whose key names it, else the unit itself. */
function sectionOf(plan: VisualPlan, unit: string): string {
  for (const n of plan.nodes) {
    if (!n.stableKey?.endsWith(UNIT_SECTION_SUFFIX)) continue;
    const key = n.stableKey.slice(0, -UNIT_SECTION_SUFFIX.length);
    if (unitsOfSectionKey(key).includes(unit)) return key;
  }
  return unit;
}

/**
 * The analysis unit at `offset` (`units.ts`'s rule, from the headings above it): a top section's own content, or one of
 * its subsections whole; before the first heading, the lead.
 */
function unitAt(text: string, offset: number): string {
  const path: { level: number; text: string }[] = [];
  let fence = false;
  let at = 0;
  for (const line of text.split("\n")) {
    if (at >= offset) break;
    at += line.length + 1;
    if (/^\s*(```|~~~)/.test(line)) fence = !fence;
    if (fence) continue;
    const h = /^(#{1,6})\s+(.*?)\s*#*\s*$/.exec(line);
    if (!h) continue;
    const level = h[1]!.length;
    while (path.length && path.at(-1)!.level >= level) path.pop();
    path.push({ level, text: h[2]!.replace(/[*_`]/g, "").trim() });
  }
  return path.length ? path.slice(0, 2).map((p) => p.text).join(" › ") : LEAD_UNIT;
}

const capital = (s: string) => (s ? s[0]!.toUpperCase() + s.slice(1) : s);

function hash(s: string): string {
  let h = 0;
  for (let i = 0; i < s.length; i++) h = (Math.imul(31, h) + s.charCodeAt(i)) | 0;
  return (h >>> 0).toString(36);
}
